const pl=(n,a)=>{const m=n%100,k=n%10;return n+" "+(m>10&&m<20?a[2]:k===1?a[0]:k>1&&k<5?a[1]:a[2])};
const ago=d=>{const sec=(Date.now()-new Date(d))/1000;if(sec<60)return"только что";if(sec<3600)return Math.floor(sec/60)+" мин назад";if(sec<86400)return Math.floor(sec/3600)+" ч назад";if(sec<604800)return Math.floor(sec/86400)+" дн назад";return fmt(d)};
